execute: async (_toolCallId, args) => {
  const params = args as Record<string, unknown>;
  const url = readStringParam(params, "url", { required: true });
  const extractMode = readStringParam(params, "extractMode") === "text" ? "text" : "markdown";
  const maxChars = readNumberParam(params, "maxChars", { integer: true });
  const maxCharsCap = resolveFetchMaxCharsCap(fetch);
  // Build SSRF policy from browser config's hostname allowlist so that url-fetch
  // respects the same hostname allowlist as browser navigation.
  const browserSsrfPolicy = options?.config?.browser?.ssrfPolicy;
  const ssrfPolicy = buildHostnameAllowlistPolicyFromSuffixAllowlist(
    browserSsrfPolicy?.hostnameAllowlist,
  );
  const result = await runWebFetch({
    url,
    extractMode,
    maxChars: resolveMaxChars(
      maxChars ?? fetch?.maxChars,
      DEFAULT_FETCH_MAX_CHARS,
      maxCharsCap,
    ),
    maxResponseBytes,
    maxRedirects: resolveMaxRedirects(fetch?.maxRedirects, DEFAULT_FETCH_MAX_REDIRECTS),
    timeoutSeconds: resolveTimeoutSeconds(fetch?.timeoutSeconds, DEFAULT_TIMEOUT_SECONDS),
    cacheTtlMs: resolveCacheTtlMs(fetch?.cacheTtlMinutes, DEFAULT_CACHE_TTL_MINUTES),
    userAgent,
    readabilityEnabled,
    firecrawlEnabled,
    firecrawlApiKey,
    firecrawlBaseUrl,
    firecrawlOnlyMainContent,
    firecrawlMaxAgeMs,
    firecrawlProxy: "auto",
    firecrawlStoreInCache: true,
    firecrawlTimeoutSeconds,
    ssrfPolicy,
  });
  return jsonResult(result);
},

