+    vi.spyOn(ssrf, "resolvePinnedHostname").mockImplementation(async (hostname) => {
+      const normalized = hostname.trim().toLowerCase().replace(/\.$/, "");
+      // Simulate Telegram CDN resolving to a public IP.
+      const addresses = ["149.154.167.220"];
+      return {
+        hostname: normalized,
+        addresses,
+        lookup: ssrf.createPinnedLookup({ hostname: normalized, addresses }),
+      };
+    });
+  });
+
+  afterEach(() => {
+    global.fetch = priorFetch;
+    vi.unstubAllEnvs();
+    vi.restoreAllMocks();
+  });
+
+  it("allows fetching from api.telegram.org when browser ssrfPolicy.hostnameAllowlist includes it", async () => {
+    const mockFetch = installMockFetch((input: RequestInfo | URL) =>
+      Promise.resolve({
+        ok: true,
+        status: 200,
+        headers: makeFetchHeaders({ "content-type": "image/jpeg" }),
+        text: async () => "fake image data",
+        url: resolveRequestUrl(input),
+      } as Response),
+    );
+
+    const tool = createWebFetchTool({
+      config: {
+        browser: {
+          color: "#FF4500",
+          ssrfPolicy: {
+            hostnameAllowlist: ["*.telegram.org", "api.telegram.org"],
+          },
+        },
+        tools: {
+          web: {
+            fetch: { cacheTtlMinutes: 0 },
+          },
+        },
+      },
+      sandboxed: false,
+    });
+
+    const result = await tool?.execute?.("call", {
+      url: "https://api.telegram.org/file/bot123456:ABC-DEF123456/photos/1.jpg",
+    });
+
+    expect(mockFetch).toHaveBeenCalled();
+    const resultObj = JSON.parse((result as { text: string }).text);
+    expect(resultObj.status).toBe(200);
+  });
+
+  it("blocks api.telegram.org when browser ssrfPolicy.hostnameAllowlist does not include it", async () => {
+    const tool = createWebFetchTool({
+      config: {
+        browser: {
+          color: "#FF4500",
+          ssrfPolicy: {
+            hostnameAllowlist: ["example.com"],
+          },
+        },
+        tools: {
+          web: {
+            fetch: { cacheTtlMinutes: 0 },
+          },
+        },
+      },
+      sandboxed: false,
+    });
+
+    await expect(
+      tool?.execute?.("call", {
+        url: "https://api.telegram.org/file/bot123456:ABC-DEF123456/photos/1.jpg",
+      }),
+    ).rejects.toThrow();
+  });
+});

